#include "stdlib/blas/ext/base/zcartesian_product.h"
#include "stdlib/blas/ext/base/zfill.h"
#include "stdlib/blas/base/zcopy.h"
#include "stdlib/ndarray/base/assert/is_row_major.h"
#include "stdlib/blas/base/shared.h"
#include "stdlib/strided/base/stride2offset.h"
#include "stdlib/complex/float64/ctor.h"

/**
* Computes the Cartesian product for two double-precision complex strided arrays.
*
* ## Notes
*
* -   Pairs are stored as rows in the output matrix, where the first column contains the first element of each pair and the second column contains the second element.
*
* @param order    storage layout
* @param M        number of indexed elements in X
* @param N        number of indexed elements in Y
* @param X        first input array
* @param strideX  stride length for X
* @param Y        second input array
* @param strideY  stride length for Y
* @param Out      output array
* @param LDO      stride length between successive contiguous vectors of the matrix Out (a.k.a., leading dimension of Out)
*/
void API_SUFFIX(stdlib_strided_zcartesian_product)( const CBLAS_LAYOUT order, const CBLAS_INT M, const CBLAS_INT N, const stdlib_complex128_t *X, const CBLAS_INT strideX, const stdlib_complex128_t *Y, const CBLAS_INT strideY, stdlib_complex128_t *Out, const CBLAS_INT LDO ) {
	CBLAS_INT sa1;
	CBLAS_INT sa2;
	CBLAS_INT ox;
	CBLAS_INT oy;

	if ( order == CblasColMajor ) {
		sa1 = 1;
		sa2 = LDO;
	} else { // order == CblasRowMajor
		sa1 = LDO;
		sa2 = 1;
	}
	ox = stdlib_strided_stride2offset( M, strideX );
	oy = stdlib_strided_stride2offset( N, strideY );
	API_SUFFIX(stdlib_strided_zcartesian_product_ndarray)( M, N, X, strideX, ox, Y, strideY, oy, Out, sa1, sa2, 0 );
}

/**
* Computes the Cartesian product for two double-precision complex strided arrays using alternative indexing semantics.
*
* ## Notes
*
* -   Pairs are stored as rows in the output matrix, where the first column contains the first element of each pair and the second column contains the second element.
*
* @param M           number of indexed elements in X
* @param N           number of indexed elements in Y
* @param X           first input array
* @param strideX     stride length for X
* @param offsetX     starting index for X
* @param Y           second input array
* @param strideY     stride length for Y
* @param offsetY     starting index for Y
* @param Out         output array
* @param strideOut1  stride length for the first dimension of Out
* @param strideOut2  stride length for the second dimension of Out
* @param offsetOut   starting index for Out
*/
void API_SUFFIX(stdlib_strided_zcartesian_product_ndarray)( const CBLAS_INT M, const CBLAS_INT N, const stdlib_complex128_t *X, const CBLAS_INT strideX, const CBLAS_INT offsetX, const stdlib_complex128_t *Y, const CBLAS_INT strideY, const CBLAS_INT offsetY, stdlib_complex128_t *Out, const CBLAS_INT strideOut1, const CBLAS_INT strideOut2, const CBLAS_INT offsetOut ) {
	const double *xView = (double *)X;
	const double *yView = (double *)Y;
	double *oView = (double *)Out;
	int64_t sa[ 2 ];
	CBLAS_INT isrm;
	CBLAS_INT sx;
	CBLAS_INT sy;
	CBLAS_INT s1;
	CBLAS_INT s2;
	CBLAS_INT iy;
	CBLAS_INT ix;
	CBLAS_INT io;
	CBLAS_INT ox;
	CBLAS_INT oy;
	CBLAS_INT oo;
	CBLAS_INT i;
	CBLAS_INT j;

	if ( M <= 0 || N <= 0 ) {
		return;
	}

	// Adjusted strides and offsets for reinterpreted arrays:
	sx = strideX * 2;
	sy = strideY * 2;
	s1 = strideOut1 * 2;
	s2 = strideOut2 * 2;
	ox = offsetX * 2;
	oy = offsetY * 2;
	oo = offsetOut * 2;

	sa[ 0 ] = strideOut1;
	sa[ 1 ] = strideOut2;
	isrm = stdlib_ndarray_is_row_major( 2, sa );
	ix = ox;
	io = oo;
	if ( isrm ) {
		for ( i = 0; i < M; i++ ) {
			iy = oy;
			for ( j = 0; j < N; j++ ) {
				oView[ io ] = xView[ ix ];
				oView[ io + 1 ] = xView[ ix + 1 ];
				oView[ io + s2 ] = yView[ iy ];
				oView[ io + s2 + 1 ] = yView[ iy + 1 ];
				iy += sy;
				io += s1;
			}
			ix += sx;
		}
		return;
	}
	// Column-major...
	io = offsetOut;
	for ( i = 0; i < M; i++ ) {
		API_SUFFIX(stdlib_strided_zfill_ndarray)( N, stdlib_complex128( xView[ ox + (i*sx) ], xView[ ox + (i*sx) + 1 ] ), Out, strideOut1, io );
		io += N * strideOut1;
	}
	io = offsetOut + strideOut2;
	for ( i = 0; i < M; i++ ) {
		API_SUFFIX(c_zcopy_ndarray)( N, Y, strideY, offsetY, Out, strideOut1, io );
		io += N * strideOut1;
	}
	return;
}
